<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ApiError, rowsOf, type Api, type Row } from '../lib/api'
import { useAccess } from '../lib/access'
const props=defineProps<{api:Api}>(), can=useAccess()
const facility=ref(''),product=ref(''),engine=ref(''),model=ref(''),reason=ref(''),minNew=ref(1),minHistory=ref(36),minSamples=ref(12),enabled=ref(false)
const facilities=ref<Row[]>([]),products=ref<Row[]>([]),evaluations=ref<Row[]>([]),checks=ref<Row[]>([]),policies=ref<Row[]>([]),result=ref<Row|null>(null),error=ref(''),success=ref(''),busy=ref(false)
onMounted(async()=>{try{facilities.value=rowsOf(await props.api('/catalogs/facilities'));products.value=rowsOf(await props.api('/catalogs/products'))}catch(e){error.value=e instanceof ApiError?e.message:'تعذر تحميل المرجعيات'}})
async function inspect(){busy.value=true;error.value='';result.value=null;try{const q=new URLSearchParams({facility_id:facility.value,product_code:product.value});if(engine.value)q.set('engine_type',engine.value);if(model.value)q.set('model_version_id',model.value);const r=await props.api<{data:Row}>('/ai/monitoring?'+q);result.value=r.data;const evalQ=new URLSearchParams({facility_id:facility.value,product_code:product.value});evaluations.value=rowsOf(await props.api('/ai/evaluations?'+evalQ));checks.value=rowsOf(await props.api('/ai/retraining-checks?facility_id='+encodeURIComponent(facility.value)));policies.value=rowsOf(await props.api('/ai/retraining-policies'))}catch(e){error.value=e instanceof ApiError?e.message:'تعذر تحميل المراقبة'}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';success.value='';try{await props.api('/ai/retraining-policies',{method:'POST',body:{facility_id:facility.value,product_code:product.value,enabled:enabled.value,min_new_months:Number(minNew.value),min_training_months:Number(minHistory.value),min_monitoring_samples:Number(minSamples.value),reason:reason.value}});success.value='حُفظت سياسة إعادة التدريب؛ لا تُفعّل النماذج تلقائيًا.';await inspect()}catch(e){error.value=e instanceof ApiError?e.message:'تعذر حفظ السياسة'}finally{busy.value=false}}
</script>
<template><section><h2>مراقبة النماذج وإعادة التدريب</h2><p>لا يوجد حكم معتمد على الانحراف حتى اعتماد حد هندسي وتوفر عينات كافية. تُقارن التوقعات ضمن نطاق نموذج ومحرك واحد.</p><p v-if="error" role="alert" class="notice danger">{{ error }}</p><p v-if="success" role="status" class="notice positive">{{ success }}</p>
<form class="panel compact-form" @submit.prevent="inspect"><label>المرفق<select v-model="facility" name="facility_id" required><option value="">اختر</option><option v-for="f in facilities" :key="String(f.id)" :value="String(f.id)">{{ f.name_ar }}</option></select></label><label>المنتج<select v-model="product" name="product_code" required><option value="">اختر</option><option v-for="p in products" :key="String(p.code)" :value="String(p.code)">{{ p.name_ar }}</option></select></label><label>المحرك، اختياري<input v-model="engine" placeholder="statistical_baseline" /></label><label>معرّف النموذج، اختياري<input v-model="model" /></label><button class="button primary" :disabled="busy">عرض المراقبة</button></form>
<div v-if="result" class="panel" role="status"><p v-if="result.status==='insufficient_samples'">عينات غير كافية</p><p v-else-if="result.status==='ambiguous_scope'">حدد محركًا ونموذجًا واحدًا للمقارنة.</p><p v-else>مقاييس وصفية فقط</p><p>العينات: {{ result.sample_count }} / {{ result.minimum_samples }} · MAE: {{ result.mae ?? 'غير متاح' }} · WAPE: {{ result.wape_percent ?? 'غير متاح' }}</p><p>لا يوجد حكم معتمد على الانحراف.</p><p>{{ result.warning }}</p></div>
<div v-if="can('ai.train') && facility && product" class="panel"><h3>سياسة إعادة التدريب المقيدة</h3><form @submit.prevent="save"><label><input v-model="enabled" type="checkbox" /> تفعيل التحقق الشهري</label><label>أشهر معتمدة جديدة<input v-model="minNew" type="number" min="1" max="120" required /></label><label>الحد الأدنى لأشهر التدريب<input v-model="minHistory" type="number" min="36" required /></label><label>حد عينات المراقبة<input v-model="minSamples" type="number" min="12" required /></label><label>سبب التغيير<textarea v-model="reason" minlength="10" required /></label><button class="button primary" :disabled="busy">حفظ السياسة</button></form><p>هذه حدود تقنية أولية؛ يلزم تقييم مستقل وموافقة لترقية أي مرشح.</p></div>
<div v-if="result" class="panel"><h3>عمليات التقييم وإعادة التدريب</h3><p>التقييمات: {{ evaluations.length }} · الفحوص: {{ checks.length }} · السياسات: {{ policies.length }}</p><ul><li v-for="c in checks" :key="String(c.id)">{{ c.period_month }} — {{ c.status }} — {{ c.reason }}</li></ul></div></section></template>
